import{_ as a,o as t,c as s,aF as r}from"./chunks/framework.CNkxH4QO.js";const i="/krawler-ekosystem/assets/etl.Chy3i0vi.jpg",u=JSON.parse('{"title":"krawler","description":"A minimalist geospatial ETL","frontmatter":{"title":"krawler","description":"A minimalist geospatial ETL"},"headers":[],"relativePath":"packages/krawler/index.md","filePath":"packages/krawler/index.md"}'),l={name:"packages/krawler/index.md"};function n(o,e,h,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="krawler" tabindex="-1">krawler <a class="header-anchor" href="#krawler" aria-label="Permalink to &quot;krawler&quot;">​</a></h1><p><em>A minimalist (geospatial) ETL.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Krawler aims at making the automated process of extracting and processing (geographic) data from heterogeneous sources easy. It can be viewed as a minimalist <strong>Extract, Transform, Load</strong> (ETL). <a href="https://en.wikipedia.org/wiki/Extract,_transform,_load" target="_blank" rel="noreferrer"><strong>ETL</strong></a> refers to a process where data is</p><ol><li><strong>extracted</strong> from heterogeneous data sources (e.g. databases or web services);</li><li><strong>transformed</strong> in a target format or structure for the purposes of querying and analysis (e.g. JSON or CSV);</li><li><strong>loaded</strong> into a final target data store (e.g. a file system or a database).</li></ol><p><img src="'+i+'" alt="ETL"></p><p>ETL naturally leads to the concept of a <strong>pipeline</strong>: a set of processing functions (called <strong>hooks</strong> in krawler) connected in series, often executed in parallel, where the output of one function is the input of the next one. The execution of a given pipeline on an input dataset to produce the associated output is a <strong>job</strong> performed by krawler.</p><p>A set of introduction articles to krawler details:</p><ul><li><a href="https://medium.com/@luc.claustres/a-minimalist-etl-using-feathersjs-part-1-1d56972d6500" target="_blank" rel="noreferrer">the underlying concepts</a></li><li><a href="https://medium.com/@luc.claustres/a-minimalist-etl-using-feathersjs-part-2-6aa89bd73d66" target="_blank" rel="noreferrer">the practical use case of geographical data processing</a></li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install the CLI globally with your preferred package manager:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-RxrMw" id="tab-zqQ8CgV" checked><label data-title="pnpm" for="tab-zqQ8CgV">pnpm</label><input type="radio" name="group-RxrMw" id="tab-J2Fta5Q"><label data-title="npm" for="tab-J2Fta5Q">npm</label><input type="radio" name="group-RxrMw" id="tab-ksd0dXh"><label data-title="yarn" for="tab-ksd0dXh">yarn</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/krawler</span></span></code></pre></div></div></div><p>Or pull the ready-to-use Docker image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kalisio/krawler</span></span></code></pre></div><p>See the <a href="./guides/installing.html">installation guide</a> for usage as a module, in development mode and as a Docker container.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The documentation is organized in two parts:</p><ul><li><strong>Guides</strong> — a progressive walkthrough of the framework: <ul><li><a href="./guides/understanding.html">Understanding Krawler</a> — main concepts and architecture</li><li><a href="./guides/installing.html">Installing Krawler</a> — CLI, module and Docker setups</li><li><a href="./guides/using.html">Using Krawler</a> — the job file, CLI options and healthcheck</li><li><a href="./guides/extending.html">Extending Krawler</a> — register your own stores, tasks, jobs and hooks</li></ul></li><li><strong>Reference</strong> — the exhaustive API: <ul><li><a href="./reference/services.html">Services</a> — stores, tasks and jobs</li><li><a href="./reference/hooks.html">Hooks</a> — the built-in processing functions</li><li><a href="./reference/known-issues.html">Known issues</a> — common pitfalls and their workarounds</li></ul></li></ul><p>If you intend to package a job image on top of Krawler, see also <a href="./../../building-jobs.html">Building Krawler jobs</a>.</p><h2 id="what-is-inside" tabindex="-1">What is inside? <a class="header-anchor" href="#what-is-inside" aria-label="Permalink to &quot;What is inside?&quot;">​</a></h2><p>Krawler is powered by <a href="https://feathersjs.com/" target="_blank" rel="noreferrer">Feathers</a> and relies on a curated stack, notably:</p><ul><li><a href="https://feathersjs.com/" target="_blank" rel="noreferrer">Feathers</a> — the underlying services and hooks framework</li><li><a href="https://lodash.com/" target="_blank" rel="noreferrer">Lodash</a> — JavaScript utility library, also used for <a href="https://lodash.com/docs/4.17.4#template" target="_blank" rel="noreferrer">templating</a></li><li><a href="https://github.com/mmomtchev/node-gdal-async" target="_blank" rel="noreferrer">gdal-async</a> — Node.js bindings of <a href="https://gdal.org/" target="_blank" rel="noreferrer">GDAL / OGR</a> used to process rasters and vectors</li><li><a href="https://github.com/sindresorhus/got" target="_blank" rel="noreferrer">got</a> — used to manage HTTP requests</li><li><a href="https://github.com/nodeca/js-yaml" target="_blank" rel="noreferrer">js-yaml</a> — used to process YAML files</li><li><a href="https://github.com/Leonidas-from-XIV/node-xml2js" target="_blank" rel="noreferrer">xml2js</a> — used to process XML files</li><li><a href="https://www.papaparse.com/" target="_blank" rel="noreferrer">Papa Parse</a> — used to read and write CSV files</li><li><a href="https://github.com/maxogden/abstract-blob-store" target="_blank" rel="noreferrer">abstract-blob-store</a> — used to abstract storage backends</li><li><a href="https://github.com/brianc/node-postgres" target="_blank" rel="noreferrer">node-postgres</a> — used to manage PostgreSQL databases</li><li><a href="https://github.com/mongodb/node-mongodb-native" target="_blank" rel="noreferrer">node-mongodb-native</a> — used to manage MongoDB databases</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Licensed under the <a href="https://github.com/kalisio/krawler-ekosystem/blob/master/packages/krawler/LICENSE.md" target="_blank" rel="noreferrer">MIT license</a>.</p><p>Copyright (c) 2026 <a href="https://kalisio.com" target="_blank" rel="noreferrer">Kalisio</a>.</p>',25)])])}const k=a(l,[["render",n]]);export{u as __pageData,k as default};
